/**
 * Core type definitions for the adapter system
 */

import type { AdapterCapabilities } from './capabilities.js';

// ============================================================================
// Adapter Interface
// ============================================================================

export interface Adapter {
  // Metadata
  readonly id: string;
  readonly name: string;
  readonly version: string;
  readonly capabilities: AdapterCapabilities;

  // Core CRUD operations
  create<T = any>(params: CreateParams): Promise<T>;
  findOne<T = any>(params: FindOneParams): Promise<T | null>;
  findMany<T = any>(params: FindManyParams): Promise<T[]>;
  update<T = any>(params: UpdateParams): Promise<T>;
  delete(params: DeleteParams): Promise<void>;

  // Batch operations
  createMany<T = any>(params: CreateManyParams): Promise<T[]>;
  updateMany(params: UpdateManyParams): Promise<number>;
  deleteMany(params: DeleteManyParams): Promise<number>;

  // Advanced operations
  upsert<T = any>(params: UpsertParams): Promise<T>;
  count(params: CountParams): Promise<number>;

  // Transaction support
  transaction<R>(callback: (trx: TransactionAdapter) => Promise<R>, options?: { isolationLevel: TransactionIsolation }): Promise<R>;

  // Lifecycle management
  initialize(): Promise<void>;
  isHealthy(): Promise<HealthStatus>;
  close(): Promise<void>;

  // Schema management
  getSchemaVersion(namespace: string): Promise<number>;
  setSchemaVersion(namespace: string, version: number): Promise<void>;
  validateSchema(schema: TableSchema): Promise<ValidationResult>;

  // Optional: Schema generation for CLI
  createSchema?(params: CreateSchemaParams): Promise<SchemaCreation>;

  /** Raw CRUD for internal tables, bypasses ORM schema resolution */
  readonly internal: InternalCrud;
}

export interface TransactionAdapter extends Omit<Adapter, 'transaction' | 'close'> {
  commit(): Promise<void>;
  rollback(): Promise<void>;
}

export interface HealthStatus {
  healthy: boolean;
  connections?: {
    active: number;
    idle: number;
    max: number;
  };
  lastError?: Error;
  uptime: number;
}

// ============================================================================
// Operation Parameters
// ============================================================================

export interface CreateParams {
  model: string; // Table name
  data: Record<string, any>; // Data to insert
  select?: string[]; // Fields to return
  namespace?: string; // Library namespace
}

export interface FindOneParams {
  model: string;
  where: WhereClause[];
  select?: string[];
  join?: JoinConfig;
  namespace?: string;
}

export interface FindManyParams extends FindOneParams {
  limit?: number;
  offset?: number;
  orderBy?: OrderBy[];
}

export interface UpdateParams {
  model: string;
  where: WhereClause[];
  data: Record<string, any>;
  select?: string[];
  namespace?: string;
}

export interface DeleteParams {
  model: string;
  where: WhereClause[];
  namespace?: string;
}

export interface CreateManyParams {
  model: string;
  data: Record<string, any>[];
  select?: string[];
  namespace?: string;
}

export interface UpdateManyParams {
  model: string;
  where: WhereClause[];
  data: Record<string, any>;
  namespace?: string;
}

export interface DeleteManyParams {
  model: string;
  where: WhereClause[];
  namespace?: string;
}

export interface UpsertParams {
  model: string;
  where: WhereClause[];
  create: Record<string, any>;
  update: Record<string, any>;
  select?: string[];
  namespace?: string;
  /** Explicit ON CONFLICT target column(s). When set, overrides columns derived from `where`. */
  conflictTarget?: string | string[];
}

export interface CountParams {
  model: string;
  where?: WhereClause[];
  namespace?: string;
}

import { describe, expect, it } from "vitest";
import { createSecFnServer } from "../index.js";
import { MemoryAdapter } from "./memory-adapter.js";

function createServer(options: { allowAdmin?: boolean; rateLimit?: boolean; namespaceScoped?: boolean; noTenant?: boolean } = {}) {
  const db = new MemoryAdapter();
  const secfn = createSecFnServer({
    db,
    encryption: { masterKey: "test-master-key", keyId: "test" },
    context: (request) => ({
      actorId: request.headers.get("x-actor-id") ?? undefined,
      tenantId: options.noTenant ? undefined : request.headers.get("x-tenant-id") ?? "tenant-a",
      namespace: options.namespaceScoped === false ? undefined : request.headers.get("x-namespace") ?? "workspace-a",
      ip: request.headers.get("x-forwarded-for") ?? "127.0.0.1",
      userAgent: request.headers.get("user-agent") ?? undefined,
      requestId: request.headers.get("x-request-id") ?? undefined,
    }),
    authorize: async () => options.allowAdmin ?? true,
    rateLimit: options.rateLimit
      ? {
        enabled: true,
        persistence: db,
        singleProcess: true,
        windowMs: 60_000,
        limits: { perIP: 1, perUser: 1, perEndpoint: 1 },
      }
      : undefined,
  });
  return { db, secfn };
}

describe("createSecFnServer", () => {
  it("requires admin authorization and returns the stable error envelope", async () => {
    const { secfn, db } = createServer({ allowAdmin: false });

    const response = await secfn.router.handle(new Request("https://app.test/secfn/admin/secrets"));
    const body = await response.json();

    expect(response.status).toBe(403);
    expect(body).toMatchObject({
      ok: false,
      error: { code: "SECFN_FORBIDDEN" },
    });
    expect(db.dump("secfn_audit_events")).toHaveLength(1);
    expect(db.dump("secfn_audit_events")[0]).toMatchObject({
      type: "permission_denied",
      resource: "admin:secrets:list",
    });
  });

  it("creates, rotates, lists, and reads secrets without returning admin plaintext", async () => {
    const { secfn, db } = createServer();

    const created = await secfn.router.handle(new Request("https://app.test/secfn/admin/secrets", {
      method: "POST",
      headers: { "content-type": "application/json", "x-actor-id": "admin" },
      body: JSON.stringify({ key: "OPENAI_API_KEY", value: "sk-test-secret" }),
    }));
    const createdBody = await created.json();
    expect(created.status).toBe(201);
    expect(createdBody.data.key).toBe("OPENAI_API_KEY");
    expect(JSON.stringify(createdBody)).not.toContain("sk-test-secret");

    const rotated = await secfn.router.handle(new Request(`https://app.test/secfn/admin/secrets/${createdBody.data.id}/rotate`, {
      method: "POST",
      headers: { "content-type": "application/json", "x-actor-id": "admin" },
      body: JSON.stringify({ value: "sk-rotated-secret" }),
    }));
    const rotatedBody = await rotated.json();
    expect(rotatedBody.data.currentVersion).toBe(2);

    const list = await secfn.router.handle(new Request("https://app.test/secfn/admin/secrets", {
      headers: { "x-actor-id": "admin" },
    }));
    const listBody = await list.json();
    expect(listBody.data).toHaveLength(1);
    expect(JSON.stringify(listBody)).not.toContain("sk-rotated-secret");

    expect(db.dump("secfn_secret_versions")).toHaveLength(2);
    expect(db.dump("secfn_audit_events").filter((event) => event.action === "rotate")).toHaveLength(1);
  });

  it("reveals secrets only after explicit admin confirmation and audits the access", async () => {
    const { secfn, db } = createServer();

