          { content: "Paris is the capital of France.", metadata: { source: "wiki" }, score: 0.9 }
        ] satisfies Document[]
    });

    const chain = new RetrievalChain({
      retriever: memoryfn,
      generator: async ({ documents }) => documents[0]?.content ?? ""
    });
    const result = await chain.run("Tell me about Paris");
    expect(result.retrieved[0]?.content).toContain("Paris");
    expect(result.answer).toContain("capital of France");

    const lang = new LangFn({ model: new MockChatModel({ responses: ["unused"] }) });
    const langChain = lang.createRagChain({
      retriever: memoryfn,
      generator: async ({ documents }) => documents.map((document) => document.content).join("\n")
    });
    await expect(langChain.run("Tell me about Paris")).resolves.toMatchObject({
      answer: expect.stringContaining("capital of France")
    });
  });

  it("rejects non-production db reranking in production mode", async () => {
    const records = [
      {
        content: "Paris is the capital of France.",
        embedding: vectorize("Paris is the capital of France."),
        metadata: { source: "wiki" },
        namespace: "default",
        createdAt: 1
      }
    ];
    const db = {
      async createMany() {
        return undefined;
      },
      async findMany() {
        return records;
      }
    } as any;

    const referenceStore = new DbVectorStore(db, new FakeEmbeddings(), { mode: "reference" });
    await expect(referenceStore.search("Tell me about Paris", { k: 1 })).resolves.toHaveLength(1);

    const productionStore = new DbVectorStore(db, new FakeEmbeddings(), { mode: "production" });
    await expect(productionStore.search("Tell me about Paris", { k: 1 })).rejects.toBeInstanceOf(
      NonProductionBackendError
    );
  });
});

function vectorize(text: string): number[] {
  const normalized = text.toLowerCase();
  return [normalized.includes("paris") ? 1 : 0, normalized.length];
}
import { secureRandomUUID } from "../utils/random.js";
import { redact } from "./redaction.js";
import { ObservabilityExporter, type ObservabilityExporterConfig } from "./exporter.js";
import type { SpanRecord, TraceStorage } from "./storage.js";

export interface TraceSpanOptions {
  traceId?: string;
  parentSpanId?: string;
  metadata?: Record<string, unknown>;
}

export interface TracerConfig extends ObservabilityExporterConfig {
  storage?: TraceStorage;
  redactionKeys?: string[];
}

class TraceSpanHandle {
  readonly traceId: string;
  readonly spanId: string;
  private readonly startedAt = Date.now();
  private finished = false;

  constructor(
    private readonly tracer: Tracer,
    private readonly name: string,
    traceId: string,
    private readonly parentSpanId: string | undefined,
    private readonly metadata: Record<string, unknown>
  ) {
    this.traceId = traceId;
    this.spanId = randomId();
  }

  async start(): Promise<void> {
    await this.tracer.emit(this.name, {
      phase: "start",
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      metadata: this.metadata
    });
  }

  async fail(error: unknown): Promise<void> {
    await this.finish("error", error);
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await this.finish("ok");
  }

  private async finish(status: "ok" | "error", error?: unknown): Promise<void> {
    if (this.finished) {
      return;
    }
    this.finished = true;

    const spanRecord: SpanRecord = {
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      name: this.name,
      metadata: this.metadata,
      status,
      startedAt: this.startedAt,
      endedAt: Date.now(),
      error: error ? serializeError(error) : undefined
    };
    await this.tracer.storage?.saveSpan(spanRecord);
    await this.tracer.emit(this.name, {
      phase: status === "ok" ? "end" : "error",
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      metadata: this.metadata,
      error: error ? serializeError(error) : undefined
    });
  }
}

export class Tracer {
  readonly storage?: TraceStorage;
  private readonly exporter: ObservabilityExporter;
  private readonly redactionKeys: string[];

  constructor(config: TracerConfig = {}) {
    this.storage = config.storage;
    this.exporter = new ObservabilityExporter(config);
    this.redactionKeys = [...(config.redactionKeys ?? [])];
  }

  createTraceId(): string {
    return randomId();
  }

  sanitize<T>(payload: T): T {
    return redact(payload, { keys: this.redactionKeys });
  }

  async emit(name: string, payload: Record<string, unknown>): Promise<Record<string, unknown>> {
    const safePayload = this.sanitize(payload) as Record<string, unknown>;
    await this.exporter.emit(name, safePayload);
    return safePayload;
  }

  async span(name: string, options: TraceSpanOptions = {}): Promise<TraceSpanHandle> {
    const handle = new TraceSpanHandle(
      this,
      name,
      options.traceId ?? this.createTraceId(),
      options.parentSpanId,
      (this.sanitize(options.metadata ?? {}) as Record<string, unknown>)
    );
    await handle.start();
    return handle;
  }

  async trace<T>(
    name: string,
    metadata: Record<string, unknown>,
    fn: () => Promise<T>,
    options: Omit<TraceSpanOptions, "metadata"> = {}
  ): Promise<T> {
    const span = await this.span(name, { ...options, metadata });
    try {
      return await fn();
    } catch (error) {
      await span.fail(error);
      throw error;
    } finally {
      await span[Symbol.asyncDispose]();
    }
  }
}

function randomId(): string {
  return secureRandomUUID();
}

function serializeError(error: unknown): Record<string, unknown> {
  if (error && typeof error === "object") {
    const candidate = error as Record<string, unknown>;
    const serialized: Record<string, unknown> = {};
    for (const field of ["name", "message", "code"] as const) {
      if (typeof candidate[field] === "string") serialized[field] = candidate[field];
    }
    if (Object.keys(serialized).length > 0) return serialized;
  }
  return { message: String(error) };
}
