const { spawnSync } = require('node:child_process');
const env = { ...process.env, GH_CONFIG_DIR: `${process.env.HOME}/.config/gh-other` };
function run(bin, args) {
  const result = spawnSync(bin, args, { encoding: 'utf8', env, maxBuffer: 64 * 1024 * 1024 });
  if (result.status !== 0) throw new Error(`${bin} ${args.join(' ')}\n${result.stderr}`);
  return result.stdout.trim();
}
function gh(args) { return JSON.parse(run('gh', args)); }
const owner = '21nCo';
const repo = 'super-functions';
const pr = 179;
const localHead = run('git', ['rev-parse', 'HEAD']);
const previousPushAt = run('git', ['show', '-s', '--format=%cI', 'df3493db5d18d48d23f5beed75368bef45d0e021']);
const query = `query($endCursor: String) {
  repository(owner: "${owner}", name: "${repo}") {
    pullRequest(number: ${pr}) {
      headRefOid
      reviewThreads(first: 100, after: $endCursor) {
        nodes {
          id isResolved path
          comments(first: 20) {
            nodes { id databaseId body author { login } createdAt outdated url diffHunk originalLine line commit { oid } originalCommit { oid } }
            pageInfo { hasNextPage endCursor }
          }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}`;
const nestedQuery = `query($threadId: ID!, $endCursor: String) {
  node(id: $threadId) {
    ... on PullRequestReviewThread {
      comments(first: 100, after: $endCursor) {
        nodes { id databaseId body author { login } createdAt outdated url diffHunk originalLine line commit { oid } originalCommit { oid } }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}`;
let cursor = null;
let threadPages = 0;
let snapshotHead = null;
const threads = [];
for (;;) {
  const args = ['api', 'graphql', '-f', `query=${query}`];
  if (cursor) args.push('-F', `endCursor=${cursor}`);
  const response = gh(args);
  const pull = response.data.repository.pullRequest;
  snapshotHead ??= pull.headRefOid;
  if (pull.headRefOid !== snapshotHead) throw new Error(`head changed during thread collection: ${snapshotHead} -> ${pull.headRefOid}`);
  threadPages += 1;
  threads.push(...pull.reviewThreads.nodes);
  const page = pull.reviewThreads.pageInfo;
  if (!page.hasNextPage) break;
  cursor = page.endCursor;
}
let nestedPages = 0;
for (const thread of threads) {
  let page = thread.comments.pageInfo;
  let nestedCursor = page.endCursor;
  while (page.hasNextPage) {
    const response = gh(['api', 'graphql', '-f', `query=${nestedQuery}`, '-F', `threadId=${thread.id}`, '-F', `endCursor=${nestedCursor}`]);
    const connection = response.data.node.comments;
    thread.comments.nodes.push(...connection.nodes);
    page = connection.pageInfo;
    nestedCursor = page.endCursor;
    nestedPages += 1;
  }
}
const prView = gh(['pr', 'view', String(pr), '--repo', `${owner}/${repo}`, '--json', 'headRefOid,reviews,comments,updatedAt,url,statusCheckRollup,mergeStateStatus']);
const inline = [];
for (let page = 1;; page += 1) {
  const batch = gh(['api', `repos/${owner}/${repo}/pulls/${pr}/comments?per_page=100&page=${page}`]);
  inline.push(...batch);
  if (batch.length < 100) break;
}
if (snapshotHead !== localHead || prView.headRefOid !== localHead) {
  throw new Error(`inconsistent snapshot local=${localHead} threads=${snapshotHead} pr=${prView.headRefOid}`);
}
const unresolved = threads.filter(t => !t.isResolved);
const compact = unresolved.map(thread => ({
  id: thread.id,
  path: thread.path,
  comments: thread.comments.nodes.map(comment => ({
    databaseId: comment.databaseId,
    author: comment.author?.login,
    createdAt: comment.createdAt,
    outdated: comment.outdated,
    commit: comment.commit?.oid,
    originalCommit: comment.originalCommit?.oid,
    line: comment.line,
    originalLine: comment.originalLine,
    url: comment.url,
    body: comment.body.replace(/\s+/g, ' ').slice(0, 700)
  }))
}));
const currentInline = inline.filter(comment => comment.commit_id === localHead);
const recentInline = inline.filter(comment => Date.parse(comment.created_at) > Date.parse(previousPushAt));
const currentReviews = prView.reviews.filter(review => review.commit?.oid === localHead || Date.parse(review.submittedAt) > Date.parse(previousPushAt));
const recentIssueComments = prView.comments.filter(comment => Date.parse(comment.createdAt) > Date.parse(previousPushAt));
const checks = prView.statusCheckRollup.map(check => ({
  name: check.name ?? check.context,
  status: check.status,
  conclusion: check.conclusion ?? check.state,
  workflow: check.workflowName
}));
console.log(JSON.stringify({
  snapshot: {
    head: localHead,
    previousPushAt,
    threadPages,
    threadCount: threads.length,
    terminalThreadPageInfo: { hasNextPage: false },
    nestedAdditionalPages: nestedPages,
    unresolvedThreadCount: unresolved.length,
    reviewCount: prView.reviews.length,
    currentOrRecentReviewCount: currentReviews.length,
    issueCommentCount: prView.comments.length,
    recentIssueCommentCount: recentIssueComments.length,
    inlineCommentCount: inline.length,
    currentHeadInlineCount: currentInline.length,
    recentInlineCount: recentInline.length,
    mergeStateStatus: prView.mergeStateStatus,
    checks
  },
  currentReviews: currentReviews.map(r => ({ author: r.author?.login, state: r.state, submittedAt: r.submittedAt, commit: r.commit?.oid, body: (r.body ?? '').replace(/\s+/g, ' ').slice(0, 1200) })),
  recentIssueComments: recentIssueComments.map(c => ({ author: c.author?.login, createdAt: c.createdAt, url: c.url, body: (c.body ?? '').replace(/\s+/g, ' ').slice(0, 1200) })),
  currentHeadInline: currentInline.map(c => ({ id: c.id, path: c.path, line: c.line, author: c.user?.login, createdAt: c.created_at, url: c.html_url, body: (c.body ?? '').replace(/\s+/g, ' ').slice(0, 1400) })),
  recentInline: recentInline.filter(c => c.commit_id !== localHead).map(c => ({ id: c.id, path: c.path, line: c.line, commit: c.commit_id, author: c.user?.login, createdAt: c.created_at, url: c.html_url, body: (c.body ?? '').replace(/\s+/g, ' ').slice(0, 1000) })),
  unresolvedThreads: compact
}, null, 2));
