  if (ctx.namespace && ctx.query.has('namespace') && ctx.query.get('namespace') !== ctx.namespace) reject();
  if (ctx.namespace && ['namespaces:create', 'namespaces:update', 'scan-runs:list'].includes(action)) reject();
