import { secureRandomUUID } from "../utils/random.js";
import { redact } from "./redaction.js";
import { ObservabilityExporter, type ObservabilityExporterConfig } from "./exporter.js";
import type { SpanRecord, TraceStorage } from "./storage.js";

export interface TraceSpanOptions {
  traceId?: string;
  parentSpanId?: string;
  metadata?: Record<string, unknown>;
}

export interface TracerConfig extends ObservabilityExporterConfig {
  storage?: TraceStorage;
  redactionKeys?: string[];
}

class TraceSpanHandle {
  readonly traceId: string;
  readonly spanId: string;
  private readonly startedAt = Date.now();
  private finished = false;

  constructor(
    private readonly tracer: Tracer,
    private readonly name: string,
    traceId: string,
    private readonly parentSpanId: string | undefined,
    private readonly metadata: Record<string, unknown>
  ) {
    this.traceId = traceId;
    this.spanId = randomId();
  }

  async start(): Promise<void> {
    await this.tracer.emit(this.name, {
      phase: "start",
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      metadata: this.metadata
    });
  }

  async fail(error: unknown): Promise<void> {
    await this.finish("error", error);
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await this.finish("ok");
  }

  private async finish(status: "ok" | "error", error?: unknown): Promise<void> {
    if (this.finished) {
      return;
    }
    this.finished = true;

    const spanRecord: SpanRecord = {
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      name: this.name,
      metadata: this.metadata,
      status,
      startedAt: this.startedAt,
      endedAt: Date.now(),
      error: error ? serializeError(error) : undefined
    };
    await this.tracer.storage?.saveSpan(spanRecord);
    await this.tracer.emit(this.name, {
      phase: status === "ok" ? "end" : "error",
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      metadata: this.metadata,
      error: error ? serializeError(error) : undefined
    });
  }
}

export class Tracer {
  readonly storage?: TraceStorage;
  private readonly exporter: ObservabilityExporter;
  private readonly redactionKeys: string[];

  constructor(config: TracerConfig = {}) {
    this.storage = config.storage;
    this.exporter = new ObservabilityExporter(config);
    this.redactionKeys = [...(config.redactionKeys ?? [])];
  }

  createTraceId(): string {
    return randomId();
  }

  sanitize<T>(payload: T): T {
    return redact(payload, { keys: this.redactionKeys });
  }

  async emit(name: string, payload: Record<string, unknown>): Promise<Record<string, unknown>> {
    const safePayload = this.sanitize(payload) as Record<string, unknown>;
    await this.exporter.emit(name, safePayload);
    return safePayload;
  }

  async span(name: string, options: TraceSpanOptions = {}): Promise<TraceSpanHandle> {
    const handle = new TraceSpanHandle(
      this,
      name,
      options.traceId ?? this.createTraceId(),
      options.parentSpanId,
      (this.sanitize(options.metadata ?? {}) as Record<string, unknown>)
    );
    await handle.start();
    return handle;
  }

  async trace<T>(
    name: string,
    metadata: Record<string, unknown>,
    fn: () => Promise<T>,
    options: Omit<TraceSpanOptions, "metadata"> = {}
  ): Promise<T> {
    const span = await this.span(name, { ...options, metadata });
    try {
      return await fn();
    } catch (error) {
      try {
        await span.fail(error);
      } catch {
        // Observability is secondary: never replace the operation's primary failure.
      }
      throw error;
    } finally {
      await span[Symbol.asyncDispose]();
    }
  }
}

function randomId(): string {
  return secureRandomUUID();
}

function serializeError(error: unknown): Record<string, unknown> {
  if (error && typeof error === "object") {
    const candidate = error as Record<string, unknown>;
    const serialized: Record<string, unknown> = {};
    for (const field of ["name", "message", "code"] as const) {
      if (typeof candidate[field] === "string") serialized[field] = candidate[field];
    }
    if (Object.keys(serialized).length > 0) return serialized;
  }
  return { message: String(error) };
}
import { Adapter, WhereClause } from "@superfunctions/db";

import { TraceNotFoundError, ValidationError } from "../core/errors.js";
import { Cost, TokenUsage, TraceScope } from "../core/types.js";

export interface TraceRecord extends TraceScope {
  traceId: string;
  id?: string;
  kind?: string;
  provider?: string;
  model?: string;
  input?: string;
  output?: string;
  usage?: TokenUsage;
  cost?: Cost;
  metadata?: Record<string, unknown>;
  status?: "ok" | "error";
  error?: Record<string, unknown>;
  createdAt?: number;
}

export interface SpanRecord {
  traceId: string;
  spanId: string;
  parentSpanId?: string;
  name: string;
  metadata?: Record<string, unknown>;
  status: "ok" | "error";
  startedAt: number;
  endedAt: number;
  error?: Record<string, unknown>;
}

export interface FeedbackRecord extends TraceScope {
  scope?: TraceScope;
  traceId: string;
  clientKey?: string;
  rating: number;
  comment?: string;
  metadata?: Record<string, unknown>;
  createdAt?: number;
}

export class TraceStorage {
  readonly supportsScope = true;
  private readonly traceTableName = "langfn_traces";
  private readonly spanTableName = "langfn_trace_spans";
  private readonly feedbackTableName = "langfn_trace_feedback";

  constructor(private readonly db: Adapter) {}

  async save(trace: TraceRecord): Promise<void> {
    await this.saveTrace(trace);
  }

  async saveTrace(trace: TraceRecord): Promise<TraceRecord> {
    const record = {
      ...trace,
      traceId: trace.traceId,
      id: trace.id ?? trace.traceId,
      createdAt: trace.createdAt ?? Date.now()
    };
    await this.db.create({
      model: this.traceTableName,
      data: record
    });
    return record;
  }

  async saveSpan(span: SpanRecord): Promise<SpanRecord> {
    await this.db.create({
      model: this.spanTableName,
      data: span
    });
    return span;
  }

  async saveFeedback(feedback: FeedbackRecord): Promise<FeedbackRecord> {
    const scope: TraceScope = {};
    for (const field of ["tenantId", "userId"] as const) {
      const top = feedback[field];
      const nested = feedback.scope?.[field];
      if (top !== undefined && nested !== undefined && top !== nested) {
        throw new ValidationError(`Conflicting feedback ${field}`);
      }
      scope[field] = top ?? nested;
    }
    const trace = await this.findOne(feedback.traceId, scope);
    if (!trace) {
      throw new TraceNotFoundError(undefined, { metadata: { traceId: feedback.traceId } });
    }

    if (feedback.clientKey) {
      const existing = await this.db.findOne<FeedbackRecord>({
        model: this.feedbackTableName,
        where: [
          { field: "traceId", operator: "eq", value: feedback.traceId },
          { field: "clientKey", operator: "eq", value: feedback.clientKey },
          ...scopeWhere(scope)
        ]
      });
      if (existing) {
        return existing;
      }
    }

    const record = {
      ...feedback,
      scope,
      tenantId: trace.tenantId,
      userId: trace.userId,
      createdAt: feedback.createdAt ?? Date.now()
    };
    await this.db.create({
      model: this.feedbackTableName,
      data: record
    });
    return record;
  }

  async listFeedback(traceId: string): Promise<FeedbackRecord[]> {
    return this.db.findMany<FeedbackRecord>({
      model: this.feedbackTableName,
      where: [{ field: "traceId", operator: "eq", value: traceId }],
      orderBy: [{ field: "createdAt", direction: "desc" }]
    });
  }

  async findMany(options: {
    limit?: number;
    offset?: number;
    model?: string;
    provider?: string;
    tenantId?: string;
    userId?: string;
  } = {}): Promise<TraceRecord[]> {
    const where: WhereClause[] = scopeWhere(options);
    if (options.model) {
      where.push({ field: "model", operator: "eq", value: options.model });
    }
    if (options.provider) {
      where.push({ field: "provider", operator: "eq", value: options.provider });
    }

    return this.db.findMany<TraceRecord>({
      model: this.traceTableName,
      where,
      limit: options.limit,
      offset: options.offset,
      orderBy: [{ field: "createdAt", direction: "desc" }]
    });
  }

  async findOne(traceId: string, scope?: TraceScope): Promise<TraceRecord | null> {
    return this.db.findOne<TraceRecord>({
      model: this.traceTableName,
      where: [{ field: "traceId", operator: "eq", value: traceId }, ...scopeWhere(scope)]
    });
  }
}

function scopeWhere(scope?: TraceScope): WhereClause[] {
  return (["tenantId", "userId"] as const).flatMap(field =>
    scope?.[field] === undefined ? [] : [{ field, operator: "eq" as const, value: scope[field] }]
  );
}
