    const row = await config.db.findOne<Record<string, unknown>>({ model, where: [{ field: 'id', operator: 'eq', value: id }, ...(ctx.tenantId ? [{ field: 'tenantId', operator: 'eq' as const, value: ctx.tenantId }] : [])] });
