import { describe, expect, it } from "vitest";
import { createSecFnServer } from "../index.js";
import { MemoryAdapter } from "./memory-adapter.js";

function createServer(options: { allowAdmin?: boolean; rateLimit?: boolean; namespaceScoped?: boolean; noTenant?: boolean; maxBodyBytes?: number } = {}) {
  const db = new MemoryAdapter();
  const secfn = createSecFnServer({
    db,
    encryption: { masterKey: "test-master-key", keyId: "test" },
    context: (request) => ({
      actorId: request.headers.get("x-actor-id") ?? undefined,
      tenantId: options.noTenant ? undefined : request.headers.get("x-tenant-id") ?? "tenant-a",
      namespace: options.namespaceScoped === false ? undefined : request.headers.get("x-namespace") ?? "workspace-a",
      ip: request.headers.get("x-forwarded-for") ?? "127.0.0.1",
      userAgent: request.headers.get("user-agent") ?? undefined,
      requestId: request.headers.get("x-request-id") ?? undefined,
    }),
    authorize: async () => options.allowAdmin ?? true,
    maxBodyBytes: options.maxBodyBytes,
    rateLimit: options.rateLimit
      ? {
        enabled: true,
        persistence: db,
        singleProcess: true,
        windowMs: 60_000,
        limits: { perIP: 1, perUser: 1, perEndpoint: 1 },
      }
      : undefined,
  });
  return { db, secfn };
}

describe("createSecFnServer", () => {
  it("bounds admin JSON bodies by default and supports a configured limit", async () => {
    for (const [server, body] of [
      [createServer().secfn, JSON.stringify({ key: "K", value: "x".repeat(1024 * 1024) })],
      [createServer({ maxBodyBytes: 16 }).secfn, JSON.stringify({ key: "K", value: "too large" })],
    ] as const) {
      const response = await server.router.handle(new Request("https://app.test/secfn/admin/secrets", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
      }));
      expect(response.status).toBe(413);
      await expect(response.json()).resolves.toMatchObject({
        ok: false,
        error: { code: "PAYLOAD_TOO_LARGE" },
      });
    }
  });

  it("returns stable non-internal codes for router-generated 404 and 405 errors", async () => {
    const { secfn } = createServer();
    const notFound = await secfn.router.handle(new Request("https://app.test/secfn/missing"));
    const methodNotAllowed = await secfn.router.handle(new Request("https://app.test/secfn/runtime/health", {
      method: "POST",
    }));

    expect(notFound.status).toBe(404);
    await expect(notFound.json()).resolves.toMatchObject({
      ok: false,
      error: { code: "SECFN_NOT_FOUND" },
    });
    expect(methodNotAllowed.status).toBe(405);
    expect(methodNotAllowed.headers.get("allow")).toBe("GET");
    await expect(methodNotAllowed.json()).resolves.toMatchObject({
      ok: false,
      error: { code: "SECFN_METHOD_NOT_ALLOWED" },
    });
  });

