describe("streaming and observability", () => {
  it("preserves the provider error when recording the failed span also fails", async () => {
    const providerError = new Error("provider unavailable");
    const tracer = new Tracer({
      storage: {
        saveSpan: async () => { throw new Error("telemetry unavailable"); }
      } as never
    });

    const result = await tracer.trace("provider.call", {}, async () => {
      throw providerError;
    }).catch((error: unknown) => error);

    expect(result).toBe(providerError);
  });

  it("keeps generated spans best-effort around successful operations", async () => {
    const invoked: string[] = [];
    const startFailure = new Tracer({
      exporter: {
        export: async (_name, payload) => {
          if (payload.phase === "start") throw new Error("start unavailable");
        }
      }
    });
    await expect(startFailure.trace("provider.call", {}, async () => {
      invoked.push("start");
      return "ok";
    })).resolves.toBe("ok");

    const finishFailure = new Tracer({
      storage: { saveSpan: async () => { throw new Error("finish unavailable"); } } as never
    });
    await expect(finishFailure.trace("provider.call", {}, async () => {
      invoked.push("finish");
      return "ok";
    })).resolves.toBe("ok");

    const noSpanStorage = new Tracer({ storage: {} as never });
    await expect(noSpanStorage.trace("provider.call", {}, async () => {
      invoked.push("optional");
      return "ok";
    })).resolves.toBe("ok");
    expect(invoked).toEqual(["start", "finish", "optional"]);
  });

  it("serializes falsy span failures and redacts stored span records", async () => {
    const spans: Array<Record<string, unknown>> = [];
    const tracer = new Tracer({
      storage: { saveSpan: async (span: Record<string, unknown>) => { spans.push(span); } } as never,
      redactionKeys: ["message"]
    });

    for (const error of [null, 0, false]) {
      await tracer.trace("provider.call", {}, async () => { throw error; }).catch(() => undefined);
    }

    expect(spans).toHaveLength(3);
    expect(spans.map((span) => span.status)).toEqual(["error", "error", "error"]);
    expect(spans.map((span) => span.error)).toEqual([
      { message: "***REDACTED***" },
      { message: "***REDACTED***" },
      { message: "***REDACTED***" }
    ]);
  });

  it("keeps generated stream span failures from replacing provider events", async () => {
    for (const phase of ["start", "end"]) {
      const client = new LangFn({
        model: new MockChatModel({
          streams: [[
            { type: "content", content: "ok", delta: "ok" },
            { type: "end", finish_reason: "stop" }
          ]]
        }),
        observability: {
          enabled: true,
          exporter: {
            export: async (_name, payload) => {
              if (payload.phase === phase) throw new Error(`${phase} unavailable`);
            }
          }
        }
      });

      await expect(collect(client.stream("hello"))).resolves.toEqual([
        expect.objectContaining({ type: "content", content: "ok" }),
        expect.objectContaining({ type: "end" })
      ]);
    }
  });

  it("normalizes the canonical stream taxonomy and enforces terminal events", async () => {
    const client = new LangFn({
      model: new MockChatModel({
        streams: [[
          { type: "content", delta: "Hel", content: "Hel" },
          { type: "content", delta: "lo", content: "lo" },
          { type: "tool_call", id: "call_1", toolName: "lookup_weather", args: { city: "Paris" } },
          { type: "tool_result", toolCallId: "call_1", result: { temperatureC: 18 } },
          { type: "reasoning", step: "1", thinking: "Need weather data" },
          { type: "trace_event", span: "langfn.provider.stream", metadata: { phase: "mid" } },
          { type: "token_usage", prompt_tokens: 3, completion_tokens: 2 },
          { type: "end", finish_reason: "stop" }
        ]]
      })
  it("keeps evaluation accuracy distinct from graded score", async () => {
    const evaluator = new Evaluator();
    const evaluation = await evaluator.evaluate({
      lang: new LangFn({ model: new MockChatModel({ responses: ["one", "two"] }) }),
      dataset: [
        { input: "one", expected: "one" },
        { input: "two", expected: "two" }
      ],
      metrics: [createMetric("graded", (_output, _expected, item) => (
        item.input === "one" ? { score: 0.5, passed: true } : { score: 0.9, passed: false }
      ))]
    });

    expect(evaluation.accuracy).toBe(0.5);
    expect(evaluation.passRate).toBe(0.5);
    expect(evaluation.avgScore).toBeCloseTo(0.7);
  });

  it("rejects duplicate metric and model identities before evaluation", async () => {
    const complete = vi.fn(async () => ({ content: "ok" }));
    const lang = new LangFn({ model: new MockChatModel({ complete }) });
    const evaluator = new Evaluator();
    const metric = createMetric("same", () => true);

    await expect(evaluator.evaluate({
      lang,
      dataset: [{ input: "x", expected: "x" }],
      metrics: [metric, metric]
    })).rejects.toBeInstanceOf(ValidationError);
    await expect(evaluator.compare({
      models: [{ name: "same", lang }, { name: "same", lang }],
      dataset: [{ input: "x", expected: "x" }]
    })).rejects.toBeInstanceOf(ValidationError);
    expect(complete).not.toHaveBeenCalled();
  });

  it("uses collision-safe comparison maps and unique TestFn run IDs", async () => {
    const evaluator = new Evaluator();
    const comparison = await evaluator.compare({
      models: [{ name: "__proto__", lang: new LangFn({ model: new MockChatModel({ responses: ["ok"] }) }) }],
      dataset: [{ input: "x", expected: "ok" }]
    });
    expect(Object.getPrototypeOf(comparison.perModel)).toBeNull();
    expect(comparison.perModel["__proto__"]).toBeInstanceOf(Object);

    const result = comparison.perModel["__proto__"];
    expect(result.toTestFnRun("same").id).not.toBe(result.toTestFnRun("same").id);
  });

  it("fails empty datasets with VALIDATION_ERROR", async () => {
    const evaluator = new Evaluator({ lang: new LangFn({ model: new MockChatModel() }) });
    await expect(evaluator.run([])).rejects.toBeInstanceOf(ValidationError);
  });
});

